package sylva.ui;

import javax.swing.*;
import java.awt.*;
import java.awt.geom.Path2D;
import java.util.Random;

/** Native Java welcome screen with a hand-drawn breathing grove. */
public final class HomePanel extends JPanel {
    private final Runnable enter;private long frame;
    public HomePanel(Runnable enter){this.enter=enter;setLayout(new GridBagLayout());setOpaque(false);JPanel content=new JPanel();content.setOpaque(false);content.setLayout(new BoxLayout(content,BoxLayout.Y_AXIS));JLabel brand=Style.eyebrow("✦   SYLVA / THE LIVING GROVE");brand.setAlignmentX(.5f);content.add(brand);content.add(Box.createVerticalStrut(32));JLabel heading=Style.title("Defend the living world.",46);heading.setAlignmentX(.5f);content.add(heading);content.add(Box.createVerticalStrut(12));JLabel sub=new JLabel("A quiet forest. A winding trail. Ten waves to endure.");sub.setFont(Style.font(15));sub.setForeground(Style.MUTED);sub.setAlignmentX(.5f);content.add(sub);content.add(Box.createVerticalStrut(32));JButton play=Style.primary("Enter the grove   ↗");play.setAlignmentX(.5f);play.addActionListener(e->enter.run());content.add(play);content.add(Box.createVerticalStrut(52));JPanel details=new JPanel(new GridLayout(1,3,12,0));details.setOpaque(false);String[][] items={{"10","seasons to survive"},{"4","living defenses"},{"∞","ways to grow"}};for(String[] item:items){JPanel card=Style.card();card.setLayout(new BoxLayout(card,BoxLayout.Y_AXIS));JLabel n=Style.title(item[0],20),d=new JLabel(item[1]);d.setForeground(Style.MUTED);d.setFont(Style.font(10));card.add(n);card.add(d);details.add(card);}details.setMaximumSize(new Dimension(470,62));details.setAlignmentX(.5f);content.add(details);GridBagConstraints c=new GridBagConstraints();c.gridx=0;c.gridy=0;c.anchor=GridBagConstraints.CENTER;add(content,c);}
    @Override protected void paintComponent(Graphics raw){Graphics2D g=(Graphics2D)raw.create();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);g.setPaint(new GradientPaint(0,0,new Color(67,72,60),getWidth(),getHeight(),new Color(36,46,39)));g.fillRect(0,0,getWidth(),getHeight());Random r=new Random(8173);for(int i=0;i<150;i++){int x=r.nextInt(Math.max(1,getWidth())),y=r.nextInt(Math.max(1,getHeight()));g.setColor(new Color(224,233,196,24+r.nextInt(60)));g.fillOval(x,y,2+r.nextInt(3),2+r.nextInt(3));}drawRoot(g,getWidth()*.08,getHeight()*.92,getWidth()*.78,getHeight()*.63,90,new Color(73,92,51));drawRoot(g,getWidth()*.92,getHeight()*.92,getWidth()*.58,getHeight()*.45,76,new Color(76,90,51));g.setColor(new Color(222,228,199,20));g.fillOval((int)(getWidth()*.10),(int)(getHeight()*.08),3,3);g.dispose();frame++;}
    private void drawRoot(Graphics2D g,double x,double y,double dx,double dy,int width,Color color){Path2D p=new Path2D.Double();p.moveTo(x,y);p.curveTo(x+dx*.25,y-dy*.1,x+dx*.55,y-dy*1.6,x+dx, y-dy);g.setColor(new Color(20,28,21,70));g.setStroke(new BasicStroke(width+20,BasicStroke.CAP_ROUND,BasicStroke.JOIN_ROUND));g.draw(p);g.setColor(new Color(color.getRed(),color.getGreen(),color.getBlue(),190));g.setStroke(new BasicStroke(width,BasicStroke.CAP_ROUND,BasicStroke.JOIN_ROUND));g.draw(p);Random r=new Random((long)x);for(int i=0;i<100;i++){double t=r.nextDouble();double px=x+dx*t,py=y-dy*t+Math.sin(t*Math.PI)*dy*.35+r.nextDouble()*45-22;g.setColor(new Color(130+r.nextInt(40),151+r.nextInt(35),78+r.nextInt(25),100+r.nextInt(90)));g.fillOval((int)px,(int)py,4+r.nextInt(8),2+r.nextInt(4));}}
}
